-- Migration 030: real, individually researched orgs for Austin, TX and
-- San Antonio, TX (30 orgs) — first of several batches expanding metro
-- coverage and filling the previously-empty music/faith categories.

insert into public.organizations
  (id, owner_id, name, description, website, logo_url, category, tags, remote, international,
   min_age, country, state, city, verified, counts_for_service_hours, commitment_type, featured)
values
  ('f1000000-0000-4000-8000-000000000001', null, 'Austin Soundwaves', 'Austin Soundwaves brings free band, orchestra, mariachi, and private lessons to more than 2,000 Central Texas students each year. Volunteers help out at concerts and events, and musicians with some skill can lend a hand supporting lessons and ensembles like the Soundwaves Symphony.', 'https://www.austinsoundwaves.org/', 'https://www.google.com/s2/favicons?domain=www.austinsoundwaves.org&sz=128', 'music', array['music or performance','teaching or tutoring','training provided','recurring'], false, false, 16, 'United States', 'TX', 'Austin', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000002', null, 'Girls Rock Austin', 'Girls Rock Austin runs summer camps where girls, gender-expansive, and BIPOC youth pick up an instrument, form a band, and play a real show by the end of the week. Volunteers coach bands, run sound, teach instruments, or just keep the whole loud, joyful week running smoothly.', 'https://www.girlsrockatx.org/', 'https://www.google.com/s2/favicons?domain=www.girlsrockatx.org&sz=128', 'music', array['music or performance','training provided','leadership role','seasonal'], false, false, 18, 'United States', 'TX', 'Austin', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000003', null, 'Catholic Charities of Central Texas', 'Catholic Charities of Central Texas fights poverty and homelessness across 25 counties, helping families in crisis, refugees, and veterans get back on their feet. Volunteers sort donated supplies, help out at events, or support programs -- you don''t have to be Catholic or religious at all to pitch in.', 'https://ccctx.org/', 'https://www.google.com/s2/favicons?domain=ccctx.org&sz=128', 'faith', array['faith-based','no experience needed','bilingual helpful','recurring'], false, false, 14, 'United States', 'TX', 'Austin', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000004', null, 'Jewish Family Service (Shalom Austin)', 'Jewish Family Service supports Austin families with counseling, case management, and the Weinberg Food Pantry. Teen volunteers can work a pantry shift once a month, sorting and packing groceries and helping clients pick out what they need with dignity.', 'https://shalomaustin.org/jfs/', 'https://www.google.com/s2/favicons?domain=shalomaustin.org&sz=128', 'faith', array['faith-based','no experience needed','monthly','recurring'], false, false, 16, 'United States', 'TX', 'Austin', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000005', null, 'Austin Free-Net', 'Austin Free-Net closes the digital divide by teaching computer and internet skills to Austinites who need it most -- job seekers, seniors, and people rebuilding after hard times. Volunteers sit one-on-one in the computer lab helping someone write a resume, set up email, or just get comfortable with a mouse and keyboard.', 'https://www.austinfree.net/', 'https://www.google.com/s2/favicons?domain=www.austinfree.net&sz=128', 'tech', array['tech skills useful','teaching or tutoring','training provided','weekly'], false, false, 16, 'United States', 'TX', 'Austin', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000006', null, 'Sustainable Food Center', 'Sustainable Food Center has been growing Austin''s local food system since the 1970s, running farmers markets, school gardens, and cooking classes. Volunteers help staff the market info booth, dig into garden work, or pack seeds for the Spread the Harvest program -- no green thumb required.', 'https://sustainablefoodcenter.org/', 'https://www.google.com/s2/favicons?domain=sustainablefoodcenter.org&sz=128', 'gardening', array['gardening skills','outdoors','no experience needed','weekly'], false, false, 15, 'United States', 'TX', 'Austin', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000007', null, 'Austin Disaster Relief Network', 'Austin Disaster Relief Network mobilizes volunteers to help families after floods, fires, and other disasters, and helps them prepare before the next one hits. You don''t need any church connection to join -- shifts run as short as two hours doing logistics, hospitality, or hands-on relief work, with on-the-job training.', 'https://adrn.org/', 'https://www.google.com/s2/favicons?domain=adrn.org&sz=128', 'disaster', array['training provided','no experience needed','physical work','one-time'], false, false, 16, 'United States', 'TX', 'Austin', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000008', null, 'Keep Austin Beautiful', 'Keep Austin Beautiful gets volunteers out cleaning up creeks, parks, and streets across the city, including big group events like the citywide Keep Austin Beautiful Day every April. It''s an easy, no-experience pick for a crew of friends who want to spend a couple hours outside making a visible difference.', 'https://keepaustinbeautiful.org/', 'https://www.google.com/s2/favicons?domain=keepaustinbeautiful.org&sz=128', 'environment', array['good for crews','outdoors','no experience needed','one-time'], false, false, 12, 'United States', 'TX', 'Austin', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000009', null, 'Special Olympics Texas', 'Special Olympics Texas runs sports training and competitions for athletes with intellectual disabilities all over the state, with its offices based in Austin. Volunteers work events as timers, greeters, or "pit crew," or use sports know-how to help coach a clinic -- no experience necessary, just enthusiasm.', 'https://www.sotx.org/', 'https://www.google.com/s2/favicons?domain=www.sotx.org&sz=128', 'sports', array['sports or coaching','no experience needed','family friendly','one-time'], false, false, 15, 'United States', 'TX', 'Austin', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000010', null, 'Central Texas Food Bank', 'Central Texas Food Bank sorts and distributes millions of pounds of food a year to neighbors facing hunger across the region. Volunteers pack boxes in the warehouse, help run mobile pantry distributions, or pitch in at the on-site kitchen and garden.', 'https://www.centraltexasfoodbank.org/', 'https://www.google.com/s2/favicons?domain=www.centraltexasfoodbank.org&sz=128', 'food', array['good for crews','no experience needed','physical work','recurring'], false, false, 12, 'United States', 'TX', 'Austin', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000011', null, 'Austin Pets Alive!', 'Austin Pets Alive! is the no-kill shelter behind Austin''s reputation as one of the safest cities in the country for shelter animals. Volunteers walk dogs, clean kennels, help with adoptions, or work the thrift store -- there''s a role whether you love animals or just want to help behind the scenes.', 'https://www.austinpetsalive.org/', 'https://www.google.com/s2/favicons?domain=www.austinpetsalive.org&sz=128', 'animals', array['animal handling','training provided','recurring','physical work'], false, false, 12, 'United States', 'TX', 'Austin', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000012', null, 'Austin Bat Cave', 'Austin Bat Cave gives Austin students free creative writing help, pairing them with volunteer tutors during the school day and at after-school workshops. If you like reading and writing, this is a chance to work one-on-one with a younger student and watch their stories come together.', 'https://austinbatcave.org/', 'https://www.google.com/s2/favicons?domain=austinbatcave.org&sz=128', 'education', array['teaching or tutoring','chill first-timer pick','weekly','training provided'], false, false, 16, 'United States', 'TX', 'Austin', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000013', null, 'Dell Children''s Medical Center', 'Dell Children''s Medical Center runs a Teen Summer Volunteer Program where high schoolers help out around the hospital, from greeting families to supporting staff on various units. It''s a great pick for anyone eyeing a future in healthcare who wants real hospital experience.', 'https://www.dellchildrens.net/', 'https://www.google.com/s2/favicons?domain=www.dellchildrens.net&sz=128', 'medicine', array['training provided','skilled volunteers wanted','indoors','recurring'], false, false, 16, 'United States', 'TX', 'Austin', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000014', null, 'Meals on Wheels Central Texas', 'Meals on Wheels Central Texas delivers over 3,000 meals a day to homebound seniors, and each delivery doubles as a quick safety check-in. Volunteers drive routes solo or with a parent, dropping off meals and a friendly face -- flexible enough to fit around a busy school schedule.', 'https://www.mealsonwheelscentraltexas.org/', 'https://www.google.com/s2/favicons?domain=www.mealsonwheelscentraltexas.org&sz=128', 'seniors', array['chill first-timer pick','weekly','family friendly','recurring'], false, false, 16, 'United States', 'TX', 'Austin', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000015', null, 'Austin Habitat for Humanity', 'Austin Habitat for Humanity builds and repairs homes for local families almost entirely with volunteer labor. No construction experience needed -- crews frame walls, paint, landscape, or help out at the ReStore, with tools and training provided on site.', 'https://austinhabitat.org/', 'https://www.google.com/s2/favicons?domain=austinhabitat.org&sz=128', 'community', array['good for crews','no experience needed','physical work','outdoors'], false, false, 16, 'United States', 'TX', 'Austin', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000016', null, 'YOSA (Youth Orchestras of San Antonio)', 'YOSA runs eleven youth orchestras plus a mariachi ensemble and summer symphony camp for more than 2,500 young musicians across San Antonio. Volunteers help at rehearsals and concerts -- including big nights at the Tobin Center -- handling everything from check-in to stage support.', 'https://www.yosa.org/', 'https://www.google.com/s2/favicons?domain=www.yosa.org&sz=128', 'music', array['music or performance','family friendly','one-time','recurring'], false, false, 14, 'United States', 'TX', 'San Antonio', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000017', null, 'Musical Bridges Around the World', 'Musical Bridges Around the World brings free concerts and music education to San Antonio, connecting international performers with underserved youth, seniors, and military families. Volunteers help staff concerts, festivals, and educational programs throughout the year.', 'https://musicalbridges.org/', 'https://www.google.com/s2/favicons?domain=musicalbridges.org&sz=128', 'music', array['music or performance','family friendly','one-time','seasonal'], false, false, 14, 'United States', 'TX', 'San Antonio', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000018', null, 'SAMMinistries', 'SAMMinistries is an interfaith nonprofit helping homeless and at-risk families across San Antonio find stable housing. Volunteers tutor kids in the homework room, tend a no-experience-needed vegetable garden alongside residents, or help with front desk and donation sorting tasks.', 'https://www.samm.org/', 'https://www.google.com/s2/favicons?domain=www.samm.org&sz=128', 'faith', array['faith-based','teaching or tutoring','gardening skills','weekly'], false, false, 16, 'United States', 'TX', 'San Antonio', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000019', null, 'Catholic Charities Archdiocese of San Antonio', 'Catholic Charities San Antonio runs more than two dozen bilingual programs helping families across 19 counties work toward self-sufficiency. After a quick background check and online training, volunteers help with food distribution, office support, and community outreach.', 'https://ccaosa.org/', 'https://www.google.com/s2/favicons?domain=ccaosa.org&sz=128', 'faith', array['faith-based','bilingual helpful','training provided','recurring'], false, false, 16, 'United States', 'TX', 'San Antonio', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000020', null, 'CoderDojo Collaborative', 'CoderDojo Collaborative runs free coding and cybersecurity clubs for kids and teens ("ninjas") ages 7 to 17 at biweekly Sunday sessions. Teen and adult volunteer mentors help newer coders work through challenges, set up laptops before sessions, and keep things running.', 'https://codingcollaborative.org/', 'https://www.google.com/s2/favicons?domain=codingcollaborative.org&sz=128', 'tech', array['tech skills useful','teaching or tutoring','training provided','weekly'], false, false, 14, 'United States', 'TX', 'San Antonio', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000021', null, 'San Antonio Botanical Garden', 'The San Antonio Botanical Garden relies on volunteers for planting, pruning, mulching, and weeding across its grounds, working alongside professional horticulturists who''ll actually teach you plant care skills. Anyone under 15 needs to come with an adult, and there''s a one-time background check fee to join the program.', 'https://sabot.org/', 'https://www.google.com/s2/favicons?domain=sabot.org&sz=128', 'gardening', array['gardening skills','outdoors','training provided','recurring'], false, false, 14, 'United States', 'TX', 'San Antonio', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000022', null, 'American Red Cross Central & South Texas', 'The Red Cross''s San Antonio chapter trains volunteers for Disaster Action Teams that show up when a fire, storm, or flood forces someone from their home. Training is provided for every role, and some support positions -- like data entry or outreach -- can even be done remotely.', 'https://www.redcross.org/local/texas/central-and-south-texas.html', 'https://www.google.com/s2/favicons?domain=www.redcross.org&sz=128', 'disaster', array['training provided','no experience needed','tech skills useful','recurring'], true, false, 16, 'United States', 'TX', 'San Antonio', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000023', null, 'Green Spaces Alliance of South Texas', 'Green Spaces Alliance protects natural land and water around San Antonio, from trail systems to community gardens. Volunteers help with trail maintenance, cleanups, community garden projects, or lead tours -- a solid pick if you like being outside and want to see real land conservation up close.', 'https://greensatx.org/', 'https://www.google.com/s2/favicons?domain=greensatx.org&sz=128', 'environment', array['outdoors','no experience needed','good for crews','gardening skills'], false, false, 12, 'United States', 'TX', 'San Antonio', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000024', null, 'San Antonio Sports', 'San Antonio Sports runs free youth sports programs reaching over 150,000 kids a year and helps stage major events like NCAA tournaments in the city. Volunteers help run youth clinics, assist at big sporting events, or support after-school sports leagues.', 'https://sanantoniosports.org/', 'https://www.google.com/s2/favicons?domain=sanantoniosports.org&sz=128', 'sports', array['sports or coaching','family friendly','one-time','good for crews'], false, false, 14, 'United States', 'TX', 'San Antonio', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000025', null, 'San Antonio Food Bank', 'The San Antonio Food Bank fights hunger across a huge swath of South Texas, and volunteers are behind almost everything it does -- sorting warehouse donations, packing boxes, prepping meals in the Community Kitchen, or even helping tend crops at its urban farm.', 'https://safoodbank.org/', 'https://www.google.com/s2/favicons?domain=safoodbank.org&sz=128', 'food', array['good for crews','no experience needed','physical work','recurring'], false, false, 12, 'United States', 'TX', 'San Antonio', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000026', null, 'San Antonio Humane Society', 'The San Antonio Humane Society is a no-kill shelter that''s cared for the city''s homeless dogs and cats since 1952. Volunteers walk dogs, help with morning cleaning and socialization, or train up to assist with adoptions -- a great pick for anyone who wants hands-on time with animals.', 'https://sahumane.org/', 'https://www.google.com/s2/favicons?domain=sahumane.org&sz=128', 'animals', array['animal handling','training provided','recurring','physical work'], false, false, 18, 'United States', 'TX', 'San Antonio', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000027', null, 'Southwest School of Art', 'Southwest School of Art is Texas''s only independent college of art, and it opens its historic campus to thousands of kids, teens, and adults through studio classes and exhibitions every year. Volunteers help run big public events like the Fiesta Arts Fair, greeting visitors and keeping things organized.', 'https://www.swschool.org/', 'https://www.google.com/s2/favicons?domain=www.swschool.org&sz=128', 'art', array['arts and crafts','one-time','seasonal','good for crews'], false, false, 14, 'United States', 'TX', 'San Antonio', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000028', null, 'Ecumenical Center', 'The Ecumenical Center has supported San Antonio''s mental and physical wellbeing since 1967 through counseling, education, and health programs open to people of all faiths and none. Volunteers help assemble comfort kits for families and first responders and support events focused on healing and wellness.', 'https://www.ecrh.org/', 'https://www.google.com/s2/favicons?domain=www.ecrh.org&sz=128', 'medicine', array['faith-based','no experience needed','one-time','indoors'], false, false, 14, 'United States', 'TX', 'San Antonio', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000029', null, 'Respite Care of San Antonio', 'Respite Care of San Antonio supports families raising kids with developmental disabilities and complex medical needs. Volunteers help with beautification projects like yard work and painting, or jump into hands-on activities and events that give caregivers a much-needed break.', 'https://respitecaresa.org/', 'https://www.google.com/s2/favicons?domain=respitecaresa.org&sz=128', 'community', array['family friendly','physical work','one-time','no experience needed'], false, false, 13, 'United States', 'TX', 'San Antonio', true, true, 'ongoing', false),
  ('f1000000-0000-4000-8000-000000000030', null, 'Operation Comfort', 'Operation Comfort supports wounded, ill, and injured service members recovering at San Antonio''s military hospitals through adaptive sports like cycling, sled hockey, and yoga. Volunteers help run clinics and events, cheering on and assisting veterans as they get back into sports and activity.', 'https://operationcomfort.org/', 'https://www.google.com/s2/favicons?domain=operationcomfort.org&sz=128', 'veterans', array['sports or coaching','training provided','one-time','physical work'], false, false, 16, 'United States', 'TX', 'San Antonio', true, true, 'ongoing', false)
on conflict (id) do nothing;

