  ('f2000000-0000-4000-8000-000000000013', 'f1000000-0000-4000-8000-000000000013', 'Teen Volunteer Program at Dell Children''s', 'medicine', 'Dell Children''s Medical Center runs a Teen Summer Volunteer Program where high schoolers help out around the hospital, from greeting families to supporting staff on various units. It''s a great pick for anyone eyeing a future in healthcare who wants real hospital experience.', array['training provided','skilled volunteers wanted','indoors','recurring'], 16, false, false, true, '4-6 hrs', 'https://supportdellchildrens.org/volunteer/', 'https://supportdellchildrens.org/volunteer/', '2026-01-01T00:00:00Z', 'Austin', 'TX'),
  ('f2000000-0000-4000-8000-000000000014', 'f1000000-0000-4000-8000-000000000014', 'Deliver with Meals on Wheels Central Texas', 'seniors', 'Meals on Wheels Central Texas delivers over 3,000 meals a day to homebound seniors, and each delivery doubles as a quick safety check-in. Volunteers drive routes solo or with a parent, dropping off meals and a friendly face -- flexible enough to fit around a busy school schedule.', array['chill first-timer pick','weekly','family friendly','recurring'], 16, false, false, true, '1-2 hrs', 'https://www.mealsonwheelscentraltexas.org/get-involved/volunteer-application', 'https://www.mealsonwheelscentraltexas.org/get-involved/volunteer-application', '2026-01-01T00:00:00Z', 'Austin', 'TX'),
  ('f2000000-0000-4000-8000-000000000015', 'f1000000-0000-4000-8000-000000000015', 'Build with Austin Habitat for Humanity', 'community', 'Austin Habitat for Humanity builds and repairs homes for local families almost entirely with volunteer labor. No construction experience needed -- crews frame walls, paint, landscape, or help out at the ReStore, with tools and training provided on site.', array['good for crews','no experience needed','physical work','outdoors'], 16, false, false, true, 'Full day', 'https://austinhabitat.org/get-involved/volunteer/', 'https://austinhabitat.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Austin', 'TX'),
  ('f2000000-0000-4000-8000-000000000016', 'f1000000-0000-4000-8000-000000000016', 'Volunteer with YOSA', 'music', 'YOSA runs eleven youth orchestras plus a mariachi ensemble and summer symphony camp for more than 2,500 young musicians across San Antonio. Volunteers help at rehearsals and concerts -- including big nights at the Tobin Center -- handling everything from check-in to stage support.', array['music or performance','family friendly','one-time','recurring'], 14, false, false, true, '2-3 hrs', 'https://www.yosa.org/', 'https://www.yosa.org/', '2026-01-01T00:00:00Z', 'San Antonio', 'TX'),
  ('f2000000-0000-4000-8000-000000000017', 'f1000000-0000-4000-8000-000000000017', 'Volunteer with Musical Bridges Around the World', 'music', 'Musical Bridges Around the World brings free concerts and music education to San Antonio, connecting international performers with underserved youth, seniors, and military families. Volunteers help staff concerts, festivals, and educational programs throughout the year.', array['music or performance','family friendly','one-time','seasonal'], 14, false, false, true, '2-3 hrs', 'https://musicalbridges.org/volunteer', 'https://musicalbridges.org/volunteer', '2026-01-01T00:00:00Z', 'San Antonio', 'TX'),
  ('f2000000-0000-4000-8000-000000000018', 'f1000000-0000-4000-8000-000000000018', 'Volunteer with SAMMinistries', 'faith', 'SAMMinistries is an interfaith nonprofit helping homeless and at-risk families across San Antonio find stable housing. Volunteers tutor kids in the homework room, tend a no-experience-needed vegetable garden alongside residents, or help with front desk and donation sorting tasks.', array['faith-based','teaching or tutoring','gardening skills','weekly'], 16, false, false, true, '1-2 hrs', 'https://www.samm.org/get-involved/volunteer/', 'https://www.samm.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'San Antonio', 'TX'),
  ('f2000000-0000-4000-8000-000000000019', 'f1000000-0000-4000-8000-000000000019', 'Volunteer with Catholic Charities Archdiocese of San Antonio', 'faith', 'Catholic Charities San Antonio runs more than two dozen bilingual programs helping families across 19 counties work toward self-sufficiency. After a quick background check and online training, volunteers help with food distribution, office support, and community outreach.', array['faith-based','bilingual helpful','training provided','recurring'], 16, false, false, true, '2-3 hrs', 'https://ccaosa.org/get-involved/', 'https://ccaosa.org/get-involved/', '2026-01-01T00:00:00Z', 'San Antonio', 'TX'),
  ('f2000000-0000-4000-8000-000000000020', 'f1000000-0000-4000-8000-000000000020', 'Mentor with CoderDojo Collaborative', 'tech', 'CoderDojo Collaborative runs free coding and cybersecurity clubs for kids and teens ("ninjas") ages 7 to 17 at biweekly Sunday sessions. Teen and adult volunteer mentors help newer coders work through challenges, set up laptops before sessions, and keep things running.', array['tech skills useful','teaching or tutoring','training provided','weekly'], 14, false, false, true, '2 hrs', 'https://codingcollaborative.org/', 'https://codingcollaborative.org/', '2026-01-01T00:00:00Z', 'San Antonio', 'TX'),
  ('f2000000-0000-4000-8000-000000000021', 'f1000000-0000-4000-8000-000000000021', 'Volunteer at San Antonio Botanical Garden', 'gardening', 'The San Antonio Botanical Garden relies on volunteers for planting, pruning, mulching, and weeding across its grounds, working alongside professional horticulturists who''ll actually teach you plant care skills. Anyone under 15 needs to come with an adult, and there''s a one-time background check fee to join the program.', array['gardening skills','outdoors','training provided','recurring'], 14, false, false, true, '2-3 hrs', 'https://sabot.org/support/volunteer', 'https://sabot.org/support/volunteer', '2026-01-01T00:00:00Z', 'San Antonio', 'TX'),
  ('f2000000-0000-4000-8000-000000000022', 'f1000000-0000-4000-8000-000000000022', 'Join a Red Cross Disaster Action Team', 'disaster', 'The Red Cross''s San Antonio chapter trains volunteers for Disaster Action Teams that show up when a fire, storm, or flood forces someone from their home. Training is provided for every role, and some support positions -- like data entry or outreach -- can even be done remotely.', array['training provided','no experience needed','tech skills useful','recurring'], 16, true, false, true, 'Flexible', 'https://www.redcross.org/local/texas/central-and-south-texas/volunteer.html', 'https://www.redcross.org/local/texas/central-and-south-texas/volunteer.html', '2026-01-01T00:00:00Z', 'San Antonio', 'TX'),
  ('f2000000-0000-4000-8000-000000000023', 'f1000000-0000-4000-8000-000000000023', 'Volunteer with Green Spaces Alliance', 'environment', 'Green Spaces Alliance protects natural land and water around San Antonio, from trail systems to community gardens. Volunteers help with trail maintenance, cleanups, community garden projects, or lead tours -- a solid pick if you like being outside and want to see real land conservation up close.', array['outdoors','no experience needed','good for crews','gardening skills'], 12, false, false, true, '2-3 hrs', 'https://greensatx.org/get-involved/', 'https://greensatx.org/get-involved/', '2026-01-01T00:00:00Z', 'San Antonio', 'TX'),
  ('f2000000-0000-4000-8000-000000000024', 'f1000000-0000-4000-8000-000000000024', 'Volunteer with San Antonio Sports', 'sports', 'San Antonio Sports runs free youth sports programs reaching over 150,000 kids a year and helps stage major events like NCAA tournaments in the city. Volunteers help run youth clinics, assist at big sporting events, or support after-school sports leagues.', array['sports or coaching','family friendly','one-time','good for crews'], 14, false, false, true, 'Full day', 'https://volunteer.sanantoniosports.org/', 'https://volunteer.sanantoniosports.org/', '2026-01-01T00:00:00Z', 'San Antonio', 'TX'),
  ('f2000000-0000-4000-8000-000000000025', 'f1000000-0000-4000-8000-000000000025', 'Volunteer with San Antonio Food Bank', 'food', 'The San Antonio Food Bank fights hunger across a huge swath of South Texas, and volunteers are behind almost everything it does -- sorting warehouse donations, packing boxes, prepping meals in the Community Kitchen, or even helping tend crops at its urban farm.', array['good for crews','no experience needed','physical work','recurring'], 12, false, false, true, '2-3 hrs', 'https://safoodbank.org/ways-to-help/give-time/', 'https://safoodbank.org/ways-to-help/give-time/', '2026-01-01T00:00:00Z', 'San Antonio', 'TX'),
  ('f2000000-0000-4000-8000-000000000026', 'f1000000-0000-4000-8000-000000000026', 'Volunteer with San Antonio Humane Society', 'animals', 'The San Antonio Humane Society is a no-kill shelter that''s cared for the city''s homeless dogs and cats since 1952. Volunteers walk dogs, help with morning cleaning and socialization, or train up to assist with adoptions -- a great pick for anyone who wants hands-on time with animals.', array['animal handling','training provided','recurring','physical work'], 18, false, false, true, '2-3 hrs', 'https://sahumane.org/volunteer/', 'https://sahumane.org/volunteer/', '2026-01-01T00:00:00Z', 'San Antonio', 'TX'),
  ('f2000000-0000-4000-8000-000000000027', 'f1000000-0000-4000-8000-000000000027', 'Volunteer at Southwest School of Art Events', 'art', 'Southwest School of Art is Texas''s only independent college of art, and it opens its historic campus to thousands of kids, teens, and adults through studio classes and exhibitions every year. Volunteers help run big public events like the Fiesta Arts Fair, greeting visitors and keeping things organized.', array['arts and crafts','one-time','seasonal','good for crews'], 14, false, false, true, 'Full day', 'https://www.swschool.org/', 'https://www.swschool.org/', '2026-01-01T00:00:00Z', 'San Antonio', 'TX'),
  ('f2000000-0000-4000-8000-000000000028', 'f1000000-0000-4000-8000-000000000028', 'Volunteer with the Ecumenical Center', 'medicine', 'The Ecumenical Center has supported San Antonio''s mental and physical wellbeing since 1967 through counseling, education, and health programs open to people of all faiths and none. Volunteers help assemble comfort kits for families and first responders and support events focused on healing and wellness.', array['faith-based','no experience needed','one-time','indoors'], 14, false, false, true, '2-3 hrs', 'https://www.ecrh.org/about-us/volunteer/', 'https://www.ecrh.org/about-us/volunteer/', '2026-01-01T00:00:00Z', 'San Antonio', 'TX'),
  ('f2000000-0000-4000-8000-000000000029', 'f1000000-0000-4000-8000-000000000029', 'Volunteer with Respite Care of San Antonio', 'community', 'Respite Care of San Antonio supports families raising kids with developmental disabilities and complex medical needs. Volunteers help with beautification projects like yard work and painting, or jump into hands-on activities and events that give caregivers a much-needed break.', array['family friendly','physical work','one-time','no experience needed'], 13, false, false, true, '2-3 hrs', 'https://respitecaresa.org/get-involved/volunteer/', 'https://respitecaresa.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'San Antonio', 'TX'),
  ('f2000000-0000-4000-8000-000000000030', 'f1000000-0000-4000-8000-000000000030', 'Volunteer with Operation Comfort', 'veterans', 'Operation Comfort supports wounded, ill, and injured service members recovering at San Antonio''s military hospitals through adaptive sports like cycling, sled hockey, and yoga. Volunteers help run clinics and events, cheering on and assisting veterans as they get back into sports and activity.', array['sports or coaching','training provided','one-time','physical work'], 16, false, false, true, '3-4 hrs', 'https://operationcomfort.org/home/', 'https://operationcomfort.org/home/', '2026-01-01T00:00:00Z', 'San Antonio', 'TX')
